hooks.command:
powershell -File - << 'PSEOF'
$file_path = '{{file_path}}'
if (Test-Path $file_path -PathType Leaf) {
    $dir = Split-Path $file_path -Parent
    $project = $dir
    while ($project -and -not (Test-Path (Join-Path $project 'package.json') -PathType Leaf)) {
        $project = Split-Path $project -Parent
    }
    if ($project -and (Test-Path (Join-Path $project 'package.json') -PathType Leaf)) {
        try { npx prettier --write $file_path 2>$null | Out-Null } catch {}
    }
}
PSEOF

powershell -File - << 'PSEOF'
$file_path = '{{file_path}}'
$content = Get-Content $file_path -ErrorAction SilentlyContinue | Select-Object -First 5
if ($content -match 'console\\.log') {
    Write-Host '[Hook] WARNING: console.log found' -ForegroundColor Red
    Select-String -Path $file_path -Pattern 'console\\.log' | ForEach-Object { Write-Host $_.Line -ForegroundColor DarkGray }
}
PSEOF

powershell -File - << 'PSEOF'
$ErrorActionPreference = 'SilentlyContinue'
$git = (Get-Command git -ErrorAction SilentlyContinue).Source
if (-not $git) { exit 0 }
$modified = & $git diff --name-only 2>$null | Where-Object { $_ -match '\.(ts|tsx|js|jsx)$' }
if ($modified) {
    $hasConsole = $false
    foreach ($f in $modified) {
        if (Test-Path $f -PathType Leaf) {
            $content = Get-Content $f -ErrorAction SilentlyContinue
            if ($content -match 'console\\.log') {
                Write-Host "[Hook] WARNING: console.log in $f" -ForegroundColor Red
                $hasConsole = $true
            }
        }
    }
    if ($hasConsole) {
        Write-Host '[Hook] Remove console.log before committing' -ForegroundColor Yellow
    }
}
exit 0
PSEOF
